//! `Date` (J4.3d): the time values, the forms and the parser as the
//! reference browser gives them (the numbers probe, Chrome 158, run in
//! UTC and in America/New_York).

use crate::agent::{Agent, AgentOptions, Outcome, TimeZone};

/// The probe's moment: Monday, 23 November 2026, 12:00 UTC.
const NOW: f64 = 1_795_435_200_000.0;

/// America/New_York as far as the probe reaches: its local mean time
/// before 1883-11-18 17:00 UTC, then Eastern time, with daylight time by
/// the rules of 2007 on, of 1987 to 2006, and New York City's of 1950
/// (the years the probe's dates fall in). A test's stand-in for the
/// embedder's zone database.
struct NewYork;

const HOUR: f64 = 3_600_000.0;
const DAY: f64 = 86_400_000.0;
const LMT: f64 = -(4.0 * 3600.0 + 56.0 * 60.0 + 2.0) * 1000.0;

/// The day number of `y`-`m`-`d` (`m` from 1).
fn days(y: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = y.div_euclid(400);
    let yoe = y - era * 400;
    let doy = (153 * ((m + 9) % 12) + 2) / 5 + d - 1;
    era * 146_097 + yoe * 365 + yoe / 4 - yoe / 100 + doy - 719_468
}

/// The `n`th Sunday (from 1; 0 for the last) of month `m` of `y`, as a
/// day number.
fn sunday(y: i64, m: i64, n: i64) -> i64 {
    if n == 0 {
        let next = if m == 12 {
            days(y + 1, 1, 1)
        } else {
            days(y, m + 1, 1)
        };
        let last = next - 1;
        return last - (last + 4).rem_euclid(7);
    }
    let first = days(y, m, 1);
    first + (7 - (first + 4).rem_euclid(7)) % 7 + (n - 1) * 7
}

impl NewYork {
    /// Whether daylight time is kept at UTC time `t`.
    fn daylight(&self, t: f64) -> bool {
        let y = 1970 + ((t / DAY).floor() / 365.2425).floor() as i64;
        let rule = |y: i64| -> Option<(i64, i64)> {
            Some(match y {
                2007.. => (sunday(y, 3, 2), sunday(y, 11, 1)),
                1987..=2006 => (sunday(y, 4, 1), sunday(y, 10, 0)),
                1950 => (sunday(y, 4, 0), sunday(y, 9, 0)),
                _ => return None,
            })
        };
        // The estimate of the year can be one off near its ends.
        (y - 1..=y + 1).any(|y| {
            rule(y).is_some_and(|(start, end)| {
                // 2:00 standard time on, 2:00 daylight time off.
                let on = start as f64 * DAY + 7.0 * HOUR;
                let off = end as f64 * DAY + 6.0 * HOUR;
                (on..off).contains(&t)
            })
        })
    }
}

impl TimeZone for NewYork {
    fn offset(&self, t: f64) -> f64 {
        if t < -2_717_650_800_000.0 {
            LMT
        } else if self.daylight(t) {
            -4.0 * HOUR
        } else {
            -5.0 * HOUR
        }
    }

    fn name(&self, t: f64) -> String {
        // Before 1883 the reference browser names the time by today's
        // rules, though its offset is mean time.
        let daylight = if t < -2_717_650_800_000.0 {
            let y = 1970 + ((t / DAY).floor() / 365.2425).floor() as i64;
            (y - 1..=y + 1).any(|y| {
                let on = sunday(y, 3, 2) as f64 * DAY + 7.0 * HOUR;
                let off = sunday(y, 11, 1) as f64 * DAY + 6.0 * HOUR;
                (on..off).contains(&t)
            })
        } else {
            self.daylight(t)
        };
        if daylight {
            "Eastern Daylight Time".into()
        } else {
            "Eastern Standard Time".into()
        }
    }
}

fn run(src: &str, zone: Option<Box<dyn TimeZone>>) -> String {
    let mut agent = Agent::new(AgentOptions::default());
    agent.set_clock(Some(Box::new(|| NOW)));
    agent.set_time_zone(zone);
    agent.scope(|scope| match scope.run_script_named(src, "d.js") {
        Ok(Outcome::Value(v)) => scope.to_text(v).unwrap_or_default(),
        Ok(Outcome::Threw(e)) => format!("throw {}", scope.to_text(e).unwrap_or_default()),
        Ok(Outcome::Terminated) => "terminated".into(),
        Err(e) => format!("compile error: {e}"),
    })
}

#[test]
fn the_arithmetic_and_the_methods_follow_the_spec() {
    // Months past either end, -0 cleared, a NaN date's setters (their
    // arguments converted first; setFullYear starts afresh), the
    // setters' order of conversion, toJSON's generic test, a date made
    // from a date keeping its milliseconds, the clock hook, Annex B's
    // year, TimeClip before truncation, and a 24th hour.
    assert_eq!(
        run(
            "var r = []; \
             r.push(new Date(Date.UTC(2020, -1, 1)).toISOString(), new Date(Date.UTC(2020, 13, 1)).toISOString()); \
             r.push(Object.is(new Date(-0).getTime(), 0), Object.is(new Date(-0.5).getTime(), 0)); \
             var d = new Date(NaN); r.push(d.setMinutes(1), d.getTime()); \
             d.setFullYear(2020); r.push(d.toISOString()); \
             var order = []; var e = new Date(0); \
             e.setHours({ valueOf: function () { order.push('h'); return 1; } }, \
                        { valueOf: function () { order.push('m'); return 2; } }); \
             r.push(order.join(''), e.getTime()); \
             var calls = 0; new Date(NaN).setSeconds({ valueOf: function () { calls++; return 1; } }); r.push(calls); \
             r.push(String(Date.prototype.toJSON.call({ valueOf: function () { return Infinity; }, \
                                                        toISOString: function () { return 'x'; } }))); \
             r.push(new Date(new Date(1500000000007)).getTime(), Date.now() === 1795435200000); \
             var y = new Date(0); y.setYear(99); r.push(new Date(2020, 0).getYear(), y.getUTCFullYear()); \
             r.push(new Date(0).getTimezoneOffset(), new Date(1e81).getTime(), new Date(-8.64e15 - 1).getTime()); \
             r.push(Date.UTC(2020, 0, 1, 0, 0, 0, 0.9), String(new Date(2020, 0, 1, 24))); \
             r.push(Object.prototype.toString.call(new Date(0)));              r.join()",
            None
        ),
        "2019-12-01T00:00:00.000Z,2021-02-01T00:00:00.000Z,true,true,NaN,NaN,\
         2020-01-01T00:00:00.000Z,hm,3720000,1,null,1500000000007,true,120,1999,0,NaN,NaN,\
         1577836800000,Thu Jan 02 2020 00:00:00 GMT+0000 (Coordinated Universal Time),[object Date]"
    );
}

